const sql=require("mssql"),mysql=require("mysql2/promise"),CLINIC_ID=1,mssqlConfig={user:"sa",password:"#Global2025*",server:"localhost",database:"ErhanOzel",port:1433,options:{encrypt:!1,trustServerCertificate:!0}},mysqlConfig={host:"127.0.0.1",user:"root",password:"",database:"pozitif_klinik"};async function categorizeData(){let e,t;try{e=await sql.connect(mssqlConfig),t=await mysql.createConnection(mysqlConfig);const s=(await e.request().query("SELECT DISTINCT GELISNO FROM UZM_ICHASTALIKLARI_HST_ANAMNEZ")).recordset.map((e=>e.GELISNO)),a=1e3;for(let e=0;e<s.length;e+=a){const i=s.slice(e,e+a);await t.execute(`UPDATE cln_examinations SET specialty_code = 'IC_HASTALIKLARI' \n                 WHERE legacy_visit_id IN (${i.join(",")}) AND clinic_id = ?`,[1]),process.stdout.write(`\rİşlenen: ${e+i.length}...`)}}catch(e){}finally{e&&await e.close(),t&&await t.end()}}categorizeData();